package com.basiclab.iot.transform.runtime.service; import com.basiclab.iot.transform.core.domain.Party; import com.basiclab.iot.transform.runtime.dal.TransformRepository; import org.springframework.stereotype.Service; import java.util.*; @Service public class PartyService { private final TransformRepository repository; public PartyService(TransformRepository repository){this.repository=repository;} public Collection<Party> list(){return repository.listParties();} public Party get(String id){return repository.party(id);} }